cat > tok_tmp.php <<'PHP'
<?php
require '/testbed/vendor/autoload.php';
use PhpCsFixer\Tokenizer\Tokens;
$cases = [
  '"${array[$i]}";',
  '"${array[\'a\'][\'b\']}";',
  '"${array[CONST_X]}";',
  '"${array[0 + 1]}";',
  '"${$name}";',
  '"${$name[0]}";',
  '"${name->foo}";',
];
foreach ($cases as $c) {
  echo "=== $c\n";
  try {
    Tokens::clearCache();
    $tokens = Tokens::fromCode("<?php\n".$c);
    foreach ($tokens as $i => $t) {
      if ($i < 1) continue;
      printf("%d: %-40s %s\n", $i, $t->getName() ?? 'null', var_export($t->getContent(), true));
    }
  } catch (\Throwable $e) { echo "ERR ".$e->getMessage()."\n"; }
}
