public function findOppositeBlockEdge(Tokens $tokens, int $type, int $searchIndex, bool $findEnd): int
{
    static $resolvingNamespaceScope = false;

    if (null === $this->namespacesAnalyzer) {
        $this->namespacesAnalyzer = new NamespacesAnalyzer();
    }

    if (null === $this->blockEdgeDefinitions) {
        $this->blockEdgeDefinitions = Tokens::getBlockEdgeDefinitions();
    }

    $blockEdgeDefinitions = $this->blockEdgeDefinitions;

    if (!isset($blockEdgeDefinitions[$type])) {
        throw new \InvalidArgumentException(sprintf('Invalid param type: "%s".', $type));
    }

    $startEdge = $blockEdgeDefinitions[$type]['start'];
    $endEdge = $blockEdgeDefinitions[$type]['end'];
    $startIndex = $searchIndex;
    $endIndex = \count($tokens) - 1;
    $indexOffset = 1;

    if (!$findEnd) {
        [$startEdge, $endEdge] = [$endEdge, $startEdge];
        $indexOffset = -1;
        $endIndex = 0;
    }

    if (!$resolvingNamespaceScope && $tokens->offsetExists($searchIndex)) {
        $resolvingNamespaceScope = true;

        try {
            $namespace = $this->namespacesAnalyzer->getNamespaceAt($tokens, $searchIndex);
            if ($namespace instanceof NamespaceAnalysis) {
                $scopeStart = $namespace->getScopeStartIndex();
                $scopeEnd = $namespace->getScopeEndIndex();
                $endIndex = $findEnd ? $scopeEnd : $scopeStart;
            }
        } catch (\InvalidArgumentException|\LogicException $exception) {
            // Keep the original collection bounds when no namespace covers the index.
        } finally {
            $resolvingNamespaceScope = false;
        }
    }

    $matchesEdge = static function (Token $token, $edge): bool {
        $isArray = $token->isArray();
        $id = $token->getId();
        $content = $token->getContent();

        if (\is_string($edge)) {
            return !$isArray && $content === $edge;
        }

        return $isArray && $id === $edge[0] && (!isset($edge[1]) || $content === $edge[1]);
    };

    if (!$matchesEdge($tokens[$startIndex], $startEdge)) {
        throw new \InvalidArgumentException(sprintf('Invalid param $startIndex - not a proper block "%s".', $findEnd ? 'start' : 'end'));
    }

    $blockLevel = 0;

    for ($index = $startIndex; $index !== $endIndex; $index += $indexOffset) {
        $token = $tokens[$index];

        if ($matchesEdge($token, $startEdge)) {
            ++$blockLevel;

            continue;
        }

        if ($matchesEdge($token, $endEdge)) {
            --$blockLevel;

            if (0 === $blockLevel) {
                break;
            }
        }
    }

    if (!$matchesEdge($tokens[$index], $endEdge)) {
        throw new \UnexpectedValueException(sprintf('Missing block "%s".', $findEnd ? 'end' : 'start'));
    }

    return $index;
}

